import React, { Component } from 'react';
import axios from 'axios';
import MyContext from '../contexts/MyContext';

class Product extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      products: [],
      categories: [],
      txtID: '',
      txtName: '',
      txtPrice: '',
      cmbCategory: '',
      cmbStatus: 'Active',
      imgProduct: '',
      isEdit: false
    };
  }

  componentDidMount() {
    this.apiGetCategories();
    this.apiGetProducts();
  }

  // Lấy danh sách danh mục để đổ vào Select Box
  apiGetCategories = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/categories', config).then((res) => {
      this.setState({
        categories: res.data,
        cmbCategory: res.data.length > 0 ? res.data[0]._id : ''
      });
    });
  };

  // Lấy danh sách món ăn
  apiGetProducts = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/products', config).then((res) => {
      this.setState({ products: res.data });
    });
  };

  // Xử lý chọn ảnh từ máy tính (Convert sang Base64)
  previewImage = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (evt) => {
        this.setState({ imgProduct: evt.target.result });
      };
      reader.readAsDataURL(file);
    }
  };

  // Chọn món ăn để sửa
  selectItem = (item) => {
    this.setState({
      txtID: item._id,
      txtName: item.name,
      txtPrice: item.price,
      cmbCategory: item.category ? item.category._id : '',
      cmbStatus: item.status || 'Active',
      imgProduct: item.image || '',
      isEdit: true
    });
  };

  // Reset Form
  resetForm = () => {
    this.setState({
      txtID: '',
      txtName: '',
      txtPrice: '',
      cmbCategory: this.state.categories.length > 0 ? this.state.categories[0]._id : '',
      cmbStatus: 'Active',
      imgProduct: '',
      isEdit: false
    });
  };

  // Thêm mới hoặc Cập nhật Món ăn
  btnSaveClick = (e) => {
    e.preventDefault();
    const { txtID, txtName, txtPrice, cmbCategory, cmbStatus, imgProduct, isEdit } = this.state;

    if (!txtName || !txtPrice || !cmbCategory) {
      alert('Vui lòng nhập đầy đủ Tên món, Giá tiền và chọn Danh mục!');
      return;
    }

    const prod = {
      name: txtName,
      price: parseInt(txtPrice),
      category: cmbCategory,
      status: cmbStatus,
      image: imgProduct
    };

    const config = { headers: { 'x-access-token': this.context.token } };

    if (isEdit) {
      axios.put(`/api/admin/products/${txtID}`, prod, config).then((res) => {
        if (res.data) {
          alert('Cập nhật món ăn thành công!');
          this.apiGetProducts();
          this.resetForm();
        }
      });
    } else {
      axios.post('/api/admin/products', prod, config).then((res) => {
        if (res.data) {
          alert('Thêm món ăn mới thành công!');
          this.apiGetProducts();
          this.resetForm();
        }
      });
    }
  };

  // Xóa món ăn
  btnDeleteClick = (id) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa món ăn này?')) {
      const config = { headers: { 'x-access-token': this.context.token } };
      axios.delete(`/api/admin/products/${id}`, config).then((res) => {
        if (res.data.success) {
          alert('Đã xóa món ăn!');
          this.apiGetProducts();
          this.resetForm();
        }
      });
    }
  };

  render() {
    const { products, categories, txtName, txtPrice, cmbCategory, cmbStatus, imgProduct, isEdit } = this.state;

    return (
      <div style={{ padding: '20px' }}>
        <h3 style={{ color: '#4A2E2B', marginBottom: '20px' }}>QUẢN LÝ THỰC ĐƠN & MÓN ĂN</h3>
        <div style={{ display: 'flex', gap: '30px' }}>
          
          {/* Cột trái: Form nhập món ăn */}
          <div style={{ flex: '1', backgroundColor: '#FFF', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
            <h4 style={{ marginBottom: '15px' }}>{isEdit ? 'Chỉnh sửa món ăn' : 'Thêm món ăn mới'}</h4>
            <form>
              <div style={{ marginBottom: '12px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Tên món ăn *</label>
                <input
                  type="text"
                  style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc' }}
                  value={txtName}
                  onChange={(e) => this.setState({ txtName: e.target.value })}
                  placeholder="VD: Phở bò, Trà sữa..."
                />
              </div>

              <div style={{ marginBottom: '12px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Giá bán (VNĐ) *</label>
                <input
                  type="number"
                  style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc' }}
                  value={txtPrice}
                  onChange={(e) => this.setState({ txtPrice: e.target.value })}
                  placeholder="VD: 45000"
                />
              </div>

              <div style={{ marginBottom: '12px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Danh mục món *</label>
                <select
                  style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc' }}
                  value={cmbCategory}
                  onChange={(e) => this.setState({ cmbCategory: e.target.value })}
                >
                  {categories.map((cate) => (
                    <option key={cate._id} value={cate._id}>{cate.name}</option>
                  ))}
                </select>
              </div>

              <div style={{ marginBottom: '12px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Trạng thái món</label>
                <select
                  style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc' }}
                  value={cmbStatus}
                  onChange={(e) => this.setState({ cmbStatus: e.target.value })}
                >
                  <option value="Active">Còn món (Active)</option>
                  <option value="Inactive">Hết món (Inactive)</option>
                </select>
              </div>

              <div style={{ marginBottom: '15px' }}>
                <label style={{ display: 'block', marginBottom: '5px' }}>Hình ảnh món ăn</label>
                <input type="file" accept="image/*" onChange={this.previewImage} style={{ marginBottom: '10px' }} />
                {imgProduct && (
                  <div>
                    <img src={imgProduct} alt="Preview" style={{ width: '100px', height: '100px', objectFit: 'cover', borderRadius: '8px' }} />
                  </div>
                )}
              </div>

              <div style={{ display: 'flex', gap: '10px' }}>
                <button
                  type="submit"
                  onClick={this.btnSaveClick}
                  style={{ flex: 1, backgroundColor: '#4A2E2B', color: '#FFF', padding: '10px', border: 'none', borderRadius: '6px', cursor: 'pointer' }}
                >
                  {isEdit ? 'CẬP NHẬT' : 'LƯU MÓN ĂN'}
                </button>
                {isEdit && (
                  <button
                    type="button"
                    onClick={this.resetForm}
                    style={{ backgroundColor: '#888', color: '#FFF', padding: '10px', border: 'none', borderRadius: '6px', cursor: 'pointer' }}
                  >
                    HỦY
                  </button>
                )}
              </div>
            </form>
          </div>

          {/* Cột phải: Bảng danh sách món ăn */}
          <div style={{ flex: '2', backgroundColor: '#FFF', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
            <h4 style={{ marginBottom: '15px' }}>Thực đơn hiện tại</h4>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
              <thead>
                <tr style={{ backgroundColor: '#F4EBE1', borderBottom: '2px solid #DDD' }}>
                  <th style={{ padding: '10px' }}>Hình ảnh</th>
                  <th style={{ padding: '10px' }}>Tên món</th>
                  <th style={{ padding: '10px' }}>Giá bán</th>
                  <th style={{ padding: '10px' }}>Danh mục</th>
                  <th style={{ padding: '10px' }}>Trạng thái</th>
                  <th style={{ padding: '10px' }}>Hành động</th>
                </tr>
              </thead>
              <tbody>
                {products.map((item) => (
                  <tr key={item._id} style={{ borderBottom: '1px solid #EEE' }}>
                    <td style={{ padding: '10px' }}>
                      {item.image ? (
                        <img src={item.image} alt={item.name} style={{ width: '50px', height: '50px', objectFit: 'cover', borderRadius: '6px' }} />
                      ) : (
                        <div style={{ width: '50px', height: '50px', backgroundColor: '#EEE', borderRadius: '6px' }} />
                      )}
                    </td>
                    <td style={{ padding: '10px', fontWeight: 'bold' }}>{item.name}</td>
                    <td style={{ padding: '10px', color: '#C85A32', fontWeight: 'bold' }}>
                      {item.price ? item.price.toLocaleString('vi-VN') + ' đ' : '0 đ'}
                    </td>
                    <td style={{ padding: '10px' }}>{item.category ? item.category.name : 'N/A'}</td>
                    <td style={{ padding: '10px' }}>
                      <span style={{
                        padding: '4px 8px', borderRadius: '12px', fontSize: '12px', color: '#FFF',
                        backgroundColor: item.status === 'Active' ? '#2E7D32' : '#C62828'
                      }}>
                        {item.status === 'Active' ? 'Còn món' : 'Hết món'}
                      </span>
                    </td>
                    <td style={{ padding: '10px' }}>
                      <button
                        onClick={() => this.selectItem(item)}
                        style={{ marginRight: '8px', backgroundColor: '#C85A32', color: '#FFF', border: 'none', padding: '4px 10px', borderRadius: '4px', cursor: 'pointer' }}
                      >
                        Sửa
                      </button>
                      <button
                        onClick={() => this.btnDeleteClick(item._id)}
                        style={{ backgroundColor: '#D32F2F', color: '#FFF', border: 'none', padding: '4px 10px', borderRadius: '4px', cursor: 'pointer' }}
                      >
                        Xóa
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

        </div>
      </div>
    );
  }
}

export default Product;
